it('passes the session and beforeSession error to onError', async () => {
  const error = new Error('setup failed');
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const onError = jest.fn(async (_session: ChatSession, _error: Error) => {});
  const provider: AIProvider = {
